        for r1 in range(r0 + 4, h):
            run_start = 0
            run_color = None
            for c in range(w + 1):
                color = grid[r0][c] if c < w else None
                if c < w and all(grid[r][c] == color for r in range(r0, r1 + 1)):
                    if run_color == color:
                        continue
                    if run_color is not None and c - run_start >= 5:
                        for r in range(r0, r1 + 1):
